// Decade counter, period 10. Same as the "tap" gate in the original LUT-based
// decade counter, but implemented as a register-transfer function (the RTF)
// instead of a lookup table (the LUT). This makes the SDF analysis go from
// ~100 ps/transfer (on the LUT) to ~10 ps/transfer (on the RTF, ignoring
// the combinational path).
module DecadeCounter(input clk, input reset, output reg [3:0] q);
  reg [3:0] q2;
  reg [3:0] q3;
  reg [3:0] q4;
  always @(posedge clk) begin
    if (reset) begin
      q <= 4'd0; q2 <= 4'd0; q3 <= 4'd0; q4 <= 4'd0;
    end else begin
      q <= 4'd1; q2 <= 4'd2; q3 <= 4'd3; q4 <= 4'd4;
      q <= q2; q2 <= q3; q3 <= q4; q4 <= q4 + 4'd1;
    end
  end
endmodule

